Do not provide any other text or markdown fences.

Here is the problem description:
<description>
Integers from $$$1$$$ to $$$n$$$ (inclusive) were sorted lexicographically (considering integers as strings). As a result, array $$$a_1, a_2, \dots, a_n$$$ was obtained.Calculate value of $$$(\sum_{i = 1}^n ((i - a_i) \mod 998244353)) \mod 10^9 + 7$$$.$$$x \mod y$$$ here means the remainder after division $$$x$$$ by $$$y$$$. This remainder is always non-negative and doesn't exceed $$$y - 1$$$. For example, $$$5 \mod 3 = 2$$$, $$$(-1) \mod 6 = 5$$$. 
</description>

Here is the input specification:
<input_spec>
The first line contains the single integer $$$n$$$ ($$$1 \leq n \leq 10^{12}$$$).
</input_spec>

Here are additional notes:
<notes>
NoteA string $$$a$$$ is lexicographically smaller than a string $$$b$$$ if and only if one of the following holds:  $$$a$$$ is a prefix of $$$b$$$, but $$$a \ne b$$$;  in the first position where $$$a$$$ and $$$b$$$ differ, the string $$$a$$$ has a letter that appears earlier in the alphabet than the corresponding letter in $$$b$$$. For example, $$$42$$$ is lexicographically smaller than $$$6$$$, because they differ in the first digit, and $$$4 &lt; 6$$$; $$$42 &lt; 420$$$, because $$$42$$$ is a prefix of $$$420$$$.Let's denote $$$998244353$$$ as $$$M$$$.In the first example, array $$$a$$$ is equal to $$$[1, 2, 3]$$$.   $$$(1 - 1) \mod M = 0 \mod M = 0$$$  $$$(2 - 2) \mod M = 0 \mod M = 0$$$  $$$(3 - 3) \mod M = 0 \mod M = 0$$$ As a result, $$$(0 + 0 + 0) \mod 10^9 + 7 = 0$$$In the second example, array $$$a$$$ is equal to $$$[1, 10, 11, 12, 2, 3, 4, 5, 6, 7, 8, 9]$$$.   $$$(1 - 1) \mod M = 0 \mod M = 0$$$  $$$(2 - 10) \mod M = (-8) \mod M = 998244345$$$  $$$(3 - 11) \mod M = (-8) \mod M = 998244345$$$  $$$(4 - 12) \mod M = (-8) \mod M = 998244345$$$  $$$(5 - 2) \mod M = 3 \mod M = 3$$$  $$$(6 - 3) \mod M = 3 \mod M = 3$$$  $$$(7 - 4) \mod M = 3 \mod M = 3$$$  $$$(8 - 5) \mod M = 3 \mod M = 3$$$  $$$(9 - 6) \mod M = 3 \mod M = 3$$$  $$$(10 - 7) \mod M = 3 \mod M = 3$$$  $$$(11 - 8) \mod M = 3 \mod M = 3$$$  $$$(12 - 9) \mod M = 3 \mod M = 3$$$ As a result, $$$(0 + 998244345 + 998244345 + 998244345 + 3 + 3 + 3 + 3 + 3 + 3 + 3 + 3) \mod 10^9 + 7$$$ $$$=$$$ $$$2994733059 \mod 10^9 + 7$$$ $$$=$$$ $$$994733045$$$
</notes>

Here are sample inputs:
<sample_inputs>
<input>
3
</input>
<input>
12
</input>
<input>
21
</input>
<input>
1000000000000
</input>
</sample_inputs>

Here is the source code:
<source_code>
#include<bits/stdc++.h>

using namespace std;

const int mo1=998244353;
const int mo2=1000000007;
long long n;
int a[15],b[15],ans;

long long dig(int *b,int l){
	long long re=0;
	for (int i=1;i<=l;i++)
		re=re*10+b[i];
	return re;
}
long long Rank(int *b,int l){
	long long ans=0;
	for (int di=1;di<=*a;di++){
		for (int i=1;i<=min(l,di);i++){
			for (int j=(i==1?1:0);j<b[i];j++){
				long long numl=0,numr=0;
				for (int p=1;p<i;p++)
					numl=numr=numl*10+b[p];
				numl=numr=numl*10+j;
				for (int p=i+1;p<=di;p++)
					numl=numl*10,numr=numr*10+9;
				numr=min(numr,n);
				if (numl<=numr)
					ans+=numr-numl+1;
			}
		}
		if (di<=l) ++ans;
	}
	return ans;
}
int F(int *a,int di){
	return ((-dig(a,di)+Rank(a,di))%mo1+mo1)%mo1;
}

int dif[15];
int q1[1000010];
int q2[1000010];
long long sq2[1000010];
void dfs(int t,int ed,int *q,int v){
	if (t==ed){
		for (int i=0;i<=9;i++)
			q[++*q]=(v+1ll*i*dif[t])%mo1;
		return;
	}
	for (int i=0;i<=9;i++)
		dfs(t+1,ed,q,(v+1ll*i*dif[t])%mo1);
}
void update(int di,int i,int j){
	memcpy(b,a,sizeof(b));
	b[i]=j;
	for (int p=i+1;p<=di;p++) b[p]=0;
	int bas=F(b,di);
	for (int p=i+1;p<=di;p++){
		b[p]=1;
		dif[p]=(F(b,di)+mo1-bas)%mo1;
		b[p]=0;
	}
	if (di-i==0){
		ans=(ans+bas)%mo2;
		//cout<<"UPD1 "<<di<<' '<<i<<' '<<j<<' '<<ans<<' '<<bas<<endl;
		return;
	}
	if (di-i==1){
		for (int p=0;p<=9;p++)
			ans=(ans+(bas+1ll*p*dif[di])%mo1)%mo2;
		//cout<<"UPD2 "<<di<<' '<<i<<' '<<j<<' '<<ans<<' '<<bas<<' '<<dif[di]<<endl;
		return;
	}
	int mid=(di+i)/2;
	*q1=*q2=0;
	dfs(i+1,mid,q1,bas);
	dfs(mid+1,di,q2,0);
	sort(q2+1,q2+*q2+1);
	int sq2=0;
	for (int i=1;i<=*q2;i++)
		sq2=(sq2+q2[i])%mo2;
	for (int i=1;i<=*q1;i++){
		int p=lower_bound(q2+1,q2+*q2+1,mo1-q1[i])-q2;
		ans=(ans+sq2+1ll*(*q2)*q1[i])%mo2;
		ans=(ans+1ll*((*q2)-p+1)*(mo2-mo1))%mo2;
	}
	//cout<<"UPD "<<di<<' '<<i<<' '<<j<<' '<<ans<<endl;
}
int main(){
	scanf("%lld",&n);
	for (long long m=n;m;a[++*a]=m%10,m/=10);
	reverse(a+1,a+*a+1);
	for (int di=1;di<=*a;di++){
		for (int i=1;i<=di;i++){
			int l=(i==1?1:0);
			int r=(di==*a?a[i]-1:9);
			for (int j=l;j<=r;j++)
				if (j!=a[i]) update(di,i,j);
		}
		ans=(ans+F(a,di))%mo2;
		//cout<<"spe "<<di<<' '<<ans<<endl;
	}
	cout<<ans<<endl;
}
</source_code>
